  /// DB-driven names: src/lib/dynamicIcon.ts ICON_MAP (admin-configured icon strings).
  static const Map<String, AIconData> dynamicMap = <String, AIconData>{'Zap': zap, 'Shield': shield, 'Sparkles': sparkles, 'Crown': crown, 'Heart': heart, 'Star': star, 'Check': check, 'Bell': bell, 'Baby': baby, 'Calendar': calendar, 'Gift': gift, 'Lock': lock, 'Camera': camera, 'Music': music, 'BookOpen': bookOpen, 'Utensils': utensils, 'Pill': pill, 'Activity': activity, 'Truck': truck, 'CreditCard': creditCard, 'Package': package, 'MapPin': mapPin, 'Phone': phone, 'MessageCircle': messageCircle, 'Sun': sun, 'Moon': moon, 'Droplets': droplets, 'Smile': smile, 'Users': users, 'Timer': timer, 'FileText': fileText, 'Wallet': wallet, 'BadgeCheck': badgeCheck, 'Send': send};

  /// Port of getDynamicIcon(name, fallback = Sparkles).
  static AIconData dynamic(String? name, {AIconData fallback = sparkles}) {
    if (name == null || name.isEmpty) return fallback;
    return dynamicMap[name] ?? fallback;
  }
